using ModuleLoadFn = CUresult (*)(CUmodule*, const void*);
using GetFuncFn = CUresult (*)(CUfunction*, CUmodule, const char*);
using SetAttrFn = CUresult (*)(CUfunction, CUfunction_attribute, int);
using LaunchFn = CUresult (*)(CUfunction, unsigned, unsigned, unsigned,
                              unsigned, unsigned, unsigned, unsigned,
                              CUstream, void**, void**);
using MemsetAsyncFn = CUresult (*)(CUdeviceptr, int, size_t, CUstream);

struct CutlassImage {
  CUmodule mod = nullptr;
  CUfunction fn = nullptr;
  CUfunction fn_sk = nullptr;
  MemsetAsyncFn memset_async = nullptr;
  CUdeviceptr ws_ptr = 0;
  size_t ws_cap = 0;
  LaunchFn launch_fn = nullptr;
  int smem_bytes = 0;

  CutlassImage() {
    void* h = dlopen("libcuda.so.1", RTLD_NOW | RTLD_GLOBAL);
    if (h == nullptr) {
      printf("e3m4 cutlass gemm: cannot dlopen libcuda.so.1\n");
      return;
    }
    auto load = reinterpret_cast<ModuleLoadFn>(dlsym(h, "cuModuleLoadData"));
    auto getf = reinterpret_cast<GetFuncFn>(dlsym(h, "cuModuleGetFunction"));
    auto setattr = reinterpret_cast<SetAttrFn>(dlsym(h, "cuFuncSetAttribute"));
    if (load == nullptr || getf == nullptr || setattr == nullptr) {
      printf("e3m4 cutlass gemm: cuModule symbols missing\n");
      return;
    }
    if (load(&mod, kCutlassCubin) != CUDA_SUCCESS) {
      mod = nullptr;
      printf("e3m4 cutlass gemm: cuModuleLoadData failed\n");
      return;
    }
    memset_async = reinterpret_cast<MemsetAsyncFn>(dlsym(h, "cuMemsetD8Async"));
    launch_fn = reinterpret_cast<LaunchFn>(dlsym(h, "cuLaunchKernel"));
    if (launch_fn == nullptr) {
      printf("e3m4 cutlass gemm: cuLaunchKernel missing\n");
      return;
    }
    if (getf(&fn, mod, kCutlassKernelSym) != CUDA_SUCCESS) {
      fn = nullptr;
      printf("e3m4 cutlass gemm: symbol not found\n");
      return;
    }
    if (getf(&fn_sk, mod, kCutlassKernelSymSK) != CUDA_SUCCESS) fn_sk = nullptr;
    smem_bytes = e3m4_cutlass::GemmKernelVoid::SharedStorageSize;
    setattr(fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, smem_bytes);
    if (fn_sk != nullptr)
      setattr(fn_sk, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
              e3m4_cutlass::GemmKernelStreamK::SharedStorageSize);
  }
};

// Holds the (grow-only) StreamK workspace tensor alive across launches.
inline tvm::ffi::Tensor& workspace_keepalive() {
  static tvm::ffi::Tensor keep;
  return keep;
}
#define g_ws_keepalive workspace_keepalive()

CutlassImage& cutlass_image() {
  static CutlassImage img;
  return img;
}

}  // namespace

struct Sm120Fp8E3m4GemmCutlass {
  static void
  run(const tvm::ffi::TensorView out,
      const tvm::ffi::TensorView mat_a,
      const tvm::ffi::TensorView mat_b,
      const tvm::ffi::TensorView scales_a,
      const tvm::ffi::TensorView scales_b,
      const int64_t use_streamk) {
    using namespace host;
    auto device = SymbolicDevice{};
    device.set_options<kDLCUDA>();
    const int M = static_cast<int>(mat_a.shape()[0]);
    const int K = static_cast<int>(mat_a.shape()[1]);
    const int N = static_cast<int>(mat_b.shape()[0]);
    TensorMatcher({M, K}).with_dtype<fp8_e4m3_t>().verify(mat_a);
    TensorMatcher({N, K}).with_dtype<fp8_e4m3_t>().verify(mat_b);
    // majorSFA == Major::K in the embedded cubin, so the SFA buffer is read as
    // [M, K/128] row-major — precisely what per-token-group quantization emits.
    TensorMatcher({M, K / 128}).with_dtype<fp32_t>().with_device(device).verify(scales_a);
    TensorMatcher({N / 128, K / 128}).with_dtype<fp32_t>().with_device(device).verify(scales_b);
    TensorMatcher({M, N}).with_dtype<bf16_t>().with_device(device).verify(out);

    host::RuntimeCheck(K % 128 == 0, "cutlass e3m4 gemm needs K % 128 == 0, got ", K);
    host::RuntimeCheck(N % 8 == 0, "cutlass e3m4 gemm needs N % 8 == 0, got ", N);

    auto& img = cutlass_image();
    host::RuntimeCheck(img.fn != nullptr, "sm120_fp8_e3m4_gemm_cutlass image unavailable");

    // Both schedulers live in the cubin. void = one CTA per output tile (best
    // when tiles already fill the 188 SMs). StreamK = persistent 188-CTA grid
    // that also splits K, which is what the mid bands (too few tiles to fill
    // the machine) need; it needs a zeroed reduction workspace per launch.
    const bool want_sk = use_streamk != 0 && img.fn_sk != nullptr;
    if (want_sk) {
      launch_gemm<e3m4_cutlass::GemmKernelStreamK>(img, img.fn_sk, M, N, K, mat_a, mat_b,
                                                   scales_a, scales_b, out, device);
      return;
    }
    launch_gemm<e3m4_cutlass::GemmKernelVoid>(img, img.fn, M, N, K, mat_a, mat_b, scales_a,
                                              scales_b, out, device);
  }

 private:
  template <typename GemmKernel>
  static void launch_gemm(CutlassImage& img, CUfunction fn, int M, int N, int K,
                          const tvm::ffi::TensorView& mat_a, const tvm::ffi::TensorView& mat_b,
                          const tvm::ffi::TensorView& scales_a, const tvm::ffi::TensorView& scales_b,
                          const tvm::ffi::TensorView& out, host::SymbolicDevice& device) {
    using namespace host;
    typename GemmKernel::Arguments args;
    args.mode = cutlass::gemm::GemmUniversalMode::kGemm;
    args.problem_shape = {M, N, K, 1};
    args.hw_info = cutlass::KernelHardwareInfo{};
    args.hw_info.device_id = mat_a.device().device_id;
    args.hw_info.sm_count = static_cast<int>(host::runtime::get_sm_count(mat_a.device().device_id));
    args.hw_info.cluster_shape = dim3(1, 1, 1);
    args.hw_info.cluster_shape_fallback = dim3(1, 1, 1);

    using StrideA = typename GemmKernel::StrideA;
    using StrideB = typename GemmKernel::StrideB;
    using StrideD = typename GemmKernel::StrideD;
    StrideA stride_a = cutlass::make_cute_packed_stride(StrideA{}, cute::make_shape(M, K, 1));
    StrideB stride_b = cutlass::make_cute_packed_stride(StrideB{}, cute::make_shape(N, K, 1));
    StrideD stride_d = cutlass::make_cute_packed_stride(StrideD{}, cute::make_shape(M, N, 1));
    auto problem = cute::make_shape(M, N, K, 1);
    e3m4_cutlass::LayoutSFA layout_sfa = e3m4_cutlass::ScaleConfig::tile_atom_to_shape_SFA(problem);
    e3m4_cutlass::LayoutSFB layout_sfb = e3m4_cutlass::ScaleConfig::tile_atom_to_shape_SFB(problem);

    args.mainloop = typename GemmKernel::MainloopArguments{
        reinterpret_cast<e3m4_cutlass::ElementA*>(mat_a.data_ptr()), stride_a,
        reinterpret_cast<e3m4_cutlass::ElementB*>(mat_b.data_ptr()), stride_b,
        static_cast<float*>(scales_a.data_ptr()), layout_sfa,
        static_cast<float*>(scales_b.data_ptr()), layout_sfb};
    args.epilogue = {{}, nullptr, stride_d,
                     static_cast<e3m4_cutlass::ElementD*>(out.data_ptr()), stride_d};
    args.epilogue.thread.alpha = 1.0f;
    (void)device;

    host::RuntimeCheck(GemmKernel::can_implement(args), "cutlass e3m4 gemm can_implement failed");
    void* ws = nullptr;
    size_t ws_size = GemmKernel::get_workspace_size(args);
    if (ws_size != 0) {
      host::RuntimeCheck(img.memset_async != nullptr, "cutlass e3m4 gemm: cuMemsetD8Async missing");
      if (ws_size > img.ws_cap) {  // grow, then keep the larger buffer
        auto ws_t = host::ffi::alloc_workspace_tensor(ws_size, mat_a.device());
        img.ws_ptr = static_cast<CUdeviceptr>(reinterpret_cast<uintptr_t>(ws_t.data_ptr()));
        img.ws_cap = ws_size;
        g_ws_keepalive = std::move(ws_t);
      }
      ws = reinterpret_cast<void*>(img.ws_ptr);
    }
    auto params = GemmKernel::to_underlying_arguments(args, ws);
    dim3 grid = GemmKernel::get_grid_shape(params);
    dim3 block = GemmKernel::get_block_shape();
    auto stream = host::LaunchKernel::resolve_device(device.unwrap());
    void* kernel_params[] = {&params};
    if (ws_size != 0) {
      // StreamK's reduction counters / partials must start clean every launch.
      CUresult rc0 = img.memset_async(img.ws_ptr, 0, ws_size, static_cast<CUstream>(stream));
      host::RuntimeCheck(rc0 == CUDA_SUCCESS, "cutlass e3m4 gemm workspace clear failed: ",
                         static_cast<int>(rc0));
    }
    CUresult rc = img.launch_fn(fn, grid.x, grid.y, grid.z, block.x, block.y, block.z,
                                img.smem_bytes, static_cast<CUstream>(stream), kernel_params, nullptr);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "cutlass e3m4 gemm cuLaunchKernel failed: ",
                       static_cast<int>(rc));
  }
};

}  // namespace sglang
